import React, { useState } from 'react';
import {
  BookOpen,
  CheckCircle2,
  Moon,
  Shield,
  X,
  Lock,
  Tag,
  Plus,
} from 'lucide-react';
import { DailyJournal, AppState } from '../types';
import { playEveningGong } from '../services/sound';

interface DailyReviewModalProps {
  isOpen: boolean;
  onClose: () => void;
  appState: AppState;
  onSaveJournal: (journal: DailyJournal) => void;
}

export const DailyReviewModal: React.FC<DailyReviewModalProps> = ({
  isOpen,
  onClose,
  appState,
  onSaveJournal,
}) => {
  const today = appState.currentDate;
  const existing = appState.dailyJournals[today];

  const [keptWordStatus, setKeptWordStatus] = useState<'yes' | 'partial' | 'no'>(
    existing?.keptWordStatus || 'yes'
  );
  const [q1, setQ1] = useState(existing?.question1 || '');
  const [q2, setQ2] = useState(existing?.question2 || '');
  const [q3, setQ3] = useState(existing?.question3 || '');
  const [triggerInput, setTriggerInput] = useState('');
  const [triggers, setTriggers] = useState<string[]>(
    existing?.unconsciousTriggers || ['Fatigue during task switching']
  );

  if (!isOpen) return null;

  const handleAddTrigger = () => {
    if (triggerInput.trim() && !triggers.includes(triggerInput.trim())) {
      setTriggers([...triggers, triggerInput.trim()]);
      setTriggerInput('');
    }
  };

  const handleRemoveTrigger = (t: string) => {
    setTriggers(triggers.filter((item) => item !== t));
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();

    const journal: DailyJournal = {
      date: today,
      timestamp: new Date().toISOString(),
      question1: q1.trim() || 'Executed scheduled baselines and protected the core wire.',
      keptWordStatus,
      question2: q2.trim() || 'No major unconscious drift identified.',
      question3: q3.trim() || 'Acted in full alignment with legacy values.',
      unconsciousTriggers: triggers,
      funeralIdentityAffirmation: appState.settings.funeralIdentitySummary,
    };

    onSaveJournal(journal);
    playEveningGong();
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4 overflow-y-auto">
      <div className="bg-[#111111] border border-[#262626] p-6 sm:p-8 max-w-2xl w-full space-y-6 shadow-2xl relative my-8">

        {/* Modal Header */}
        <div className="flex items-start justify-between gap-4 border-b border-[#262626] pb-4">
          <div className="space-y-1">
            <div className="flex items-center gap-2">
              <span className="p-1 bg-[#161616] text-[#5FBF8C] border border-[#262626]">
                <Moon className="w-3.5 h-3.5" />
              </span>
              <span className="text-[10px] uppercase font-mono tracking-widest text-[#5FBF8C]">
                20:20 Evening Protocol
              </span>
            </div>
            <h2 className="text-xl font-serif text-[#E0E0E0]">
              Daily Structured Review (3 Inquiries)
            </h2>
            <p className="text-xs text-[#808080] font-serif italic">
              Honest audit of today&apos;s output units, unconscious slip-ups, and character trajectory.
            </p>
          </div>

          <button
            onClick={onClose}
            className="p-1 text-[#808080] hover:text-[#E0E0E0] transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        <form onSubmit={handleSave} className="space-y-5">

          {/* Inquiry 1: Did I keep my word today? */}
          <div className="space-y-2">
            <div className="flex items-center justify-between">
              <label className="text-xs font-serif text-[#E0E0E0] block">
                1. Did I keep my word today?
              </label>

              {/* Kept Word Status Selector */}
              <div className="flex items-center gap-1.5">
                {(['yes', 'partial', 'no'] as const).map((status) => (
                  <button
                    key={status}
                    type="button"
                    onClick={() => setKeptWordStatus(status)}
                    className={`px-3 py-1 text-xs font-mono uppercase tracking-widest transition-all ${
                      keptWordStatus === status
                        ? status === 'yes'
                          ? 'bg-[#6BBF8E] text-black font-semibold'
                          : status === 'partial'
                          ? 'bg-[#5FBF8C] text-black font-semibold'
                          : 'bg-[#E06C75] text-white font-semibold'
                        : 'bg-[#161616] border border-[#262626] text-[#808080] hover:text-[#E0E0E0]'
                    }`}
                  >
                    {status}
                  </button>
                ))}
              </div>
            </div>

            <textarea
              rows={2}
              placeholder="Describe physical evidence of kept commitments or exact failure points..."
              value={q1}
              onChange={(e) => setQ1(e.target.value)}
              className="w-full px-3 py-2 bg-[#0A0A0A] border border-[#262626] text-xs text-[#E0E0E0] focus:outline-none focus:border-[#5FBF8C] placeholder-[#555]"
              required
            />
          </div>

          {/* Inquiry 2: Where did I act unconsciously? */}
          <div className="space-y-2">
            <label className="text-xs font-serif text-[#E0E0E0] block">
              2. Where did I act unconsciously? (Habitual drift, distraction, avoidance)
            </label>
            <textarea
              rows={2}
              placeholder="e.g. Scrolled phone for 20 minutes before afternoon deep work sprint due to task resistance..."
              value={q2}
              onChange={(e) => setQ2(e.target.value)}
              className="w-full px-3 py-2 bg-[#0A0A0A] border border-[#262626] text-xs text-[#E0E0E0] focus:outline-none focus:border-[#5FBF8C] placeholder-[#555]"
              required
            />

            {/* Triggers Tags */}
            <div className="pt-1">
              <div className="flex flex-wrap gap-1.5 mb-2">
                {triggers.map((t) => (
                  <span
                    key={t}
                    className="text-[10px] font-mono px-2 py-0.5 bg-[#161616] text-[#A3A3A3] border border-[#262626] flex items-center gap-1.5"
                  >
                    <span>{t}</span>
                    <button
                      type="button"
                      onClick={() => handleRemoveTrigger(t)}
                      className="text-[#808080] hover:text-[#E0E0E0]"
                    >
                      ×
                    </button>
                  </span>
                ))}
              </div>

              <div className="flex gap-2">
                <input
                  type="text"
                  placeholder="Add unconscious trigger tag (e.g. Phone on desk, Post-lunch slump)"
                  value={triggerInput}
                  onChange={(e) => setTriggerInput(e.target.value)}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter') {
                      e.preventDefault();
                      handleAddTrigger();
                    }
                  }}
                  className="flex-1 px-3 py-1.5 bg-[#0A0A0A] border border-[#262626] text-xs text-[#E0E0E0] placeholder-[#555] focus:outline-none focus:border-[#5FBF8C]"
                />
                <button
                  type="button"
                  onClick={handleAddTrigger}
                  className="px-4 py-1.5 bg-[#161616] hover:bg-[#222222] border border-[#262626] text-[#E0E0E0] text-xs font-semibold uppercase tracking-widest"
                >
                  Add Tag
                </button>
              </div>
            </div>
          </div>

          {/* Inquiry 3: Did I move toward my funeral identity? */}
          <div className="space-y-2">
            <div className="flex items-center justify-between">
              <label className="text-xs font-serif text-[#E0E0E0] block">
                3. Did I move toward my funeral identity?
              </label>
            </div>

            {/* Funeral Identity Callout */}
            <div className="p-3 bg-[#0A0A0A] border border-[#262626] text-xs text-[#808080] font-serif italic">
              &ldquo;{appState.settings.funeralIdentitySummary}&rdquo;
            </div>

            <textarea
              rows={2}
              placeholder="Reflect on today's actions in light of who you intend to be remembered as..."
              value={q3}
              onChange={(e) => setQ3(e.target.value)}
              className="w-full px-3 py-2 bg-[#0A0A0A] border border-[#262626] text-xs text-[#E0E0E0] focus:outline-none focus:border-[#5FBF8C] placeholder-[#555]"
              required
            />
          </div>

          {/* Bottom Actions */}
          <div className="flex items-center justify-between pt-4 border-t border-[#262626]">
            <div className="text-[10px] text-[#808080] font-mono flex items-center gap-1">
              <Lock className="w-3 h-3 text-[#5FBF8C]" />
              <span>Saves & reinforces evening shutdown</span>
            </div>

            <div className="flex gap-3">
              <button
                type="button"
                onClick={onClose}
                className="px-4 py-2 border border-[#262626] text-[#808080] hover:text-[#E0E0E0] text-xs uppercase tracking-widest"
              >
                Cancel
              </button>
              <button
                type="submit"
                className="px-5 py-2 bg-[#5FBF8C] hover:bg-[#7FD1A6] text-black text-xs uppercase tracking-widest font-semibold flex items-center gap-1.5 shadow-md"
              >
                <CheckCircle2 className="w-4 h-4" />
                <span>Save Review</span>
              </button>
            </div>
          </div>
        </form>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import {
  Zap,
  ShieldCheck,
  CheckCircle2,
  X,
  Sparkles,
  Bot,
  Loader2,
  Clock,
  ArrowRight,
} from 'lucide-react';
import { playBaselineChime } from '../services/sound';

interface RecoveryModalProps {
  isOpen: boolean;
  onClose: () => void;
  defaultMissedAction?: string;
  onExecuteRecovery: (actionDescription: string) => void;
}

export const RecoveryModal: React.FC<RecoveryModalProps> = ({
  isOpen,
  onClose,
  defaultMissedAction = 'Deep Work Focus Block',
  onExecuteRecovery,
}) => {
  const [missedAction, setMissedAction] = useState(defaultMissedAction);
  const [context, setContext] = useState('Low energy / Schedule disruption');
  const [customAction, setCustomAction] = useState('');
  const [aiActions, setAiActions] = useState<any[]>([]);
  const [recalibrationQuote, setRecalibrationQuote] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  if (!isOpen) return null;

  const handleGenerateAiRecovery = async () => {
    setIsLoading(true);
    try {
      const res = await fetch('/api/ai/recovery-action', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ missedAction, context }),
      });
      if (!res.ok) throw new Error('Failed to generate recovery');
      const data = await res.json();
      if (data.actions) {
        setAiActions(data.actions);
      }
      if (data.recalibration) {
        setRecalibrationQuote(data.recalibration);
      }
    } catch (e) {
      console.error(e);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSelectAction = (actionDesc: string) => {
    onExecuteRecovery(actionDesc);
    playBaselineChime();
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4 overflow-y-auto">
      <div className="bg-[#111111] border border-[#262626] p-6 sm:p-8 max-w-xl w-full space-y-6 shadow-2xl relative my-8">

        {/* Header */}
        <div className="flex items-start justify-between gap-4 border-b border-[#262626] pb-4">
          <div className="space-y-1">
            <div className="flex items-center gap-2">
              <span className="p-1 bg-[#161616] text-[#5FBF8C] border border-[#262626]">
                <Zap className="w-3.5 h-3.5" />
              </span>
              <span className="text-[10px] uppercase font-mono tracking-widest text-[#5FBF8C]">
                Zero-Debt Protocol
              </span>
            </div>
            <h2 className="text-xl font-serif text-[#E0E0E0]">
              Lightweight Micro-Recovery
            </h2>
            <p className="text-xs text-[#808080] font-serif italic">
              Never accumulate &ldquo;catch-up debt&rdquo;. Execute a 2–10 minute Minimum Viable Action to preserve the continuity of identity.
            </p>
          </div>

          <button
            onClick={onClose}
            className="p-1 text-[#808080] hover:text-[#E0E0E0] transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Axiom Callout */}
        <div className="p-3.5 bg-[#161616] border border-[#262626] text-xs text-[#5FBF8C] font-serif italic leading-relaxed">
          <strong>Steward Principle:</strong> Inconsistency is not a moral verdict. Do not double tomorrow&apos;s workload. Fulfill an immediate micro-baseline right now.
        </div>

        {/* Input Parameters */}
        <div className="space-y-3">
          <div>
            <label className="text-[10px] uppercase tracking-widest text-[#808080] block mb-1">Missed Baseline or Friction Point</label>
            <input
              type="text"
              value={missedAction}
              onChange={(e) => setMissedAction(e.target.value)}
              className="w-full px-3 py-2 bg-[#0A0A0A] border border-[#262626] text-xs text-[#E0E0E0] focus:outline-none focus:border-[#5FBF8C] placeholder-[#555]"
              placeholder="e.g. Missed 90 min deep work block"
            />
          </div>

          <div className="flex justify-end">
            <button
              id="generate-ai-recovery-btn"
              onClick={handleGenerateAiRecovery}
              disabled={isLoading || !missedAction.trim()}
              className="px-4 py-1.5 bg-[#161616] hover:bg-[#222222] text-[#E0E0E0] border border-[#262626] text-[10px] uppercase tracking-widest font-semibold flex items-center gap-1.5"
            >
              {isLoading ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Bot className="w-3.5 h-3.5 text-[#5FBF8C]" />}
              <span>Generate Micro-Actions</span>
            </button>
          </div>
        </div>

        {/* Recalibration Quote */}
        {recalibrationQuote && (
          <div className="p-3 bg-[#0A0A0A] border border-[#262626] text-xs text-[#5FBF8C] font-serif italic">
            &ldquo;{recalibrationQuote}&rdquo;
          </div>
        )}

        {/* Recovery Action Options */}
        <div className="space-y-2.5">
          <span className="text-[10px] uppercase tracking-widest font-mono text-[#808080] block">
            Select Immediate Action:
          </span>

          {aiActions.length > 0 ? (
            aiActions.map((act, idx) => (
              <button
                key={idx}
                onClick={() => handleSelectAction(`${act.title} (${act.outputUnit})`)}
                className="w-full p-4 bg-[#0A0A0A] hover:bg-[#161616] border border-[#262626] hover:border-[#5FBF8C]/50 text-left transition-all flex items-start justify-between gap-3 group"
              >
                <div className="space-y-1">
                  <div className="flex items-center gap-2">
                    <span className="text-[9px] font-mono uppercase px-1.5 py-0.5 bg-[#161616] text-[#5FBF8C] border border-[#262626]">
                      {act.duration}
                    </span>
                    <span className="text-xs font-serif text-[#E0E0E0] group-hover:text-[#5FBF8C]">
                      {act.title}
                    </span>
                  </div>
                  <p className="text-xs text-[#808080] font-serif">{act.description}</p>
                  <div className="text-[10px] font-mono text-[#808080]">
                    Output: <span className="text-[#E0E0E0]">{act.outputUnit}</span>
                  </div>
                </div>
                <ArrowRight className="w-4 h-4 text-[#808080] group-hover:text-[#5FBF8C] mt-1 flex-shrink-0" />
              </button>
            ))
          ) : (
            <>
              {/* Default Option 1: 2-Minute MVA */}
              <button
                id="default-recovery-mva-btn"
                onClick={() => handleSelectAction('2-Minute Minimum Viable Action (1 sentence or 5 pushups)')}
                className="w-full p-4 bg-[#0A0A0A] hover:bg-[#161616] border border-[#262626] hover:border-[#5FBF8C]/50 text-left transition-all flex items-start justify-between gap-3 group"
              >
                <div className="space-y-1">
                  <div className="flex items-center gap-2">
                    <span className="text-[9px] font-mono uppercase px-1.5 py-0.5 bg-[#161616] text-[#5FBF8C] border border-[#262626] font-bold">
                      2 MIN
                    </span>
                    <span className="text-xs font-serif text-[#E0E0E0] group-hover:text-[#5FBF8C]">
                      Minimum Viable Action (MVA)
                    </span>
                  </div>
                  <p className="text-xs text-[#808080] font-serif">
                    Open the single document, write 1 clean line or do 5 slow deep breaths with physical movement.
                  </p>
                </div>
                <ArrowRight className="w-4 h-4 text-[#808080] group-hover:text-[#5FBF8C] mt-1 flex-shrink-0" />
              </button>

              {/* Default Option 2: 10-Minute Single Output Sprint */}
              <button
                id="default-recovery-10m-btn"
                onClick={() => handleSelectAction('10-Minute Unbroken Sprint (1 physical output unit delivered)')}
                className="w-full p-4 bg-[#0A0A0A] hover:bg-[#161616] border border-[#262626] hover:border-[#5FBF8C]/50 text-left transition-all flex items-start justify-between gap-3 group"
              >
                <div className="space-y-1">
                  <div className="flex items-center gap-2">
                    <span className="text-[9px] font-mono uppercase px-1.5 py-0.5 bg-[#161616] text-[#6BBF8E] border border-[#262626] font-bold">
                      10 MIN
                    </span>
                    <span className="text-xs font-serif text-[#E0E0E0] group-hover:text-[#5FBF8C]">
                      Single-Task Micro-Sprint
                    </span>
                  </div>
                  <p className="text-xs text-[#808080] font-serif">
                    Timer running, zero tabs, produce 1 tangible unit (1 function, 1 paragraph, 1 quick log).
                  </p>
                </div>
                <ArrowRight className="w-4 h-4 text-[#808080] group-hover:text-[#5FBF8C] mt-1 flex-shrink-0" />
              </button>
            </>
          )}
        </div>

        {/* Custom Action Input */}
        <div className="pt-3 border-t border-[#262626] flex gap-2">
          <input
            type="text"
            placeholder="Or write custom micro-recovery action..."
            value={customAction}
            onChange={(e) => setCustomAction(e.target.value)}
            className="flex-1 px-3 py-2 bg-[#0A0A0A] border border-[#262626] text-xs text-[#E0E0E0] placeholder-[#555] focus:outline-none focus:border-[#5FBF8C]"
          />
          <button
            onClick={() => {
              if (customAction.trim()) handleSelectAction(customAction.trim());
            }}
            disabled={!customAction.trim()}
            className="px-5 py-2 bg-[#5FBF8C] hover:bg-[#7FD1A6] disabled:opacity-40 text-black text-xs uppercase tracking-widest font-semibold"
          >
            Execute
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import {
  Calendar,
  Plus,
  CheckCircle2,
  Circle,
  Tag,
  Clock,
  Layers,
  ChevronLeft,
  ChevronRight,
  ArrowRight,
  Filter,
  Trash2,
} from 'lucide-react';
import { AppState, AgendaTask } from '../types';
import { formatDateDisplay, cn } from '../lib/utils';
import { playBaselineChime } from '../services/sound';

interface AgendaViewProps {
  appState: AppState;
  onToggleTask: (taskId: string) => void;
  onAddTask: (task: Partial<AgendaTask>) => void;
  onDeleteTask: (taskId: string) => void;
  onMoveTaskDate: (taskId: string, targetDate: string) => void;
}

export const AgendaView: React.FC<AgendaViewProps> = ({
  appState,
  onToggleTask,
  onAddTask,
  onDeleteTask,
  onMoveTaskDate,
}) => {
  const [selectedRoleFilter, setSelectedRoleFilter] = useState<string>('all');
  const [showAddModal, setShowAddModal] = useState(false);
  const [targetDateForAdd, setTargetDateForAdd] = useState<string>(appState.currentDate);

  // Form State
  const [title, setTitle] = useState('');
  const [outputUnit, setOutputUnit] = useState('');
  const [priority, setPriority] = useState<'high' | 'medium' | 'low'>('medium');
  const [roleGoalId, setRoleGoalId] = useState('');
  const [estimatedMinutes, setEstimatedMinutes] = useState(45);

  // Generate 7 days of the current week starting from Monday
  const getDaysOfWeek = () => {
    const today = new Date();
    const currentDay = today.getDay(); // 0 is Sunday, 1 is Monday...
    const distanceToMonday = currentDay === 0 ? -6 : 1 - currentDay;

    const monday = new Date(today);
    monday.setDate(today.getDate() + distanceToMonday);

    const days = [];
    for (let i = 0; i < 7; i++) {
      const d = new Date(monday);
      d.setDate(monday.getDate() + i);
      const dateStr = d.toISOString().split('T')[0];
      const dayName = d.toLocaleDateString('en-US', { weekday: 'short' });
      const dayNum = d.getDate();
      days.push({
        dateStr,
        dayName,
        dayNum,
        isToday: dateStr === appState.currentDate,
      });
    }
    return days;
  };

  const weekDays = getDaysOfWeek();

  const handleOpenAddForDate = (dateStr: string) => {
    setTargetDateForAdd(dateStr);
    setShowAddModal(true);
  };

  const handleCreate = (e: React.FormEvent) => {
    e.preventDefault();
    if (!title.trim()) return;

    onAddTask({
      title: title.trim(),
      outputUnit: outputUnit.trim() || '1 physical output unit delivered',
      date: targetDateForAdd,
      dayOfWeek: new Date(targetDateForAdd).getDay(),
      priority,
      roleGoalId: roleGoalId || undefined,
      estimatedMinutes,
      completed: false,
    });

    setTitle('');
    setOutputUnit('');
    setShowAddModal(false);
  };

  // Filter tasks
  const filteredTasks = appState.agendaTasks.filter((t) => {
    if (selectedRoleFilter !== 'all' && t.roleGoalId !== selectedRoleFilter) {
      return false;
    }
    return true;
  });

  return (
    <div className="space-y-8 pb-12">
      {/* Header */}
      <div className="bg-[#111111] border border-[#262626] p-6 sm:p-8 flex flex-col md:flex-row items-start md:items-center justify-between gap-6">
        <div>
          <div className="flex items-center gap-2">
            <span className="text-[10px] uppercase font-mono tracking-widest px-2 py-0.5 bg-[#161616] text-[#5FBF8C] border border-[#262626]">
              Output Deliverables Board
            </span>
          </div>
          <h1 className="text-2xl sm:text-3xl font-serif text-[#E0E0E0] mt-2 tracking-tight">
            Weekly Agenda & Finite Outputs
          </h1>
          <p className="text-xs text-[#808080] max-w-2xl mt-1 leading-relaxed italic font-serif">
            Strict separation from recurring routines. Every agenda task must specify an objective physical output unit.
          </p>
        </div>

        {/* Filter by Role Goal */}
        <div className="flex items-center gap-3 w-full md:w-auto">
          <div className="flex items-center gap-2 bg-[#161616] px-3 py-2 border border-[#262626] text-xs">
            <Filter className="w-3.5 h-3.5 text-[#808080]" />
            <select
              value={selectedRoleFilter}
              onChange={(e) => setSelectedRoleFilter(e.target.value)}
              className="bg-transparent text-[#E0E0E0] focus:outline-none text-xs"
            >
              <option value="all">All Monthly Roles</option>
              {appState.monthlyRoleGoals.map((r) => (
                <option key={r.id} value={r.id}>
                  {r.roleName}
                </option>
              ))}
            </select>
          </div>

          <button
            id="agenda-add-task-btn"
            onClick={() => handleOpenAddForDate(appState.currentDate)}
            className="px-5 py-2.5 bg-[#5FBF8C] hover:bg-[#7FD1A6] text-black text-xs uppercase tracking-widest font-semibold flex items-center gap-2 shadow-sm flex-shrink-0"
          >
            <Plus className="w-4 h-4" />
            <span>Add Agenda</span>
          </button>
        </div>
      </div>

      {/* 7-Day Columns Board */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-7 gap-4">
        {weekDays.map((day) => {
          const dayTasks = filteredTasks.filter((t) => t.date === day.dateStr);
          const completedCount = dayTasks.filter((t) => t.completed).length;

          return (
            <div
              key={day.dateStr}
              className={`border flex flex-col min-h-[380px] transition-all ${
                day.isToday
                  ? 'bg-[#161616] border-[#5FBF8C]/40 shadow-sm'
                  : 'bg-[#111111] border-[#262626]'
              }`}
            >
              {/* Day Column Header */}
              <div className={`p-3.5 border-b flex items-center justify-between ${
                day.isToday ? 'border-[#5FBF8C]/30 bg-[#1A1A1A]' : 'border-[#262626]'
              }`}>
                <div>
                  <div className="flex items-center gap-2">
                    <span className="text-xs uppercase tracking-widest font-medium text-[#E0E0E0]">
                      {day.dayName}
                    </span>
                    <span className={`text-xs font-mono font-bold px-1.5 py-0.2 ${
                      day.isToday ? 'bg-[#5FBF8C] text-black' : 'text-[#808080]'
                    }`}>
                      {day.dayNum}
                    </span>
                  </div>
                  <div className="text-[10px] text-[#808080] font-mono mt-0.5">
                    {completedCount}/{dayTasks.length} Done
                  </div>
                </div>

                <button
                  id={`add-task-day-${day.dateStr}`}
                  onClick={() => handleOpenAddForDate(day.dateStr)}
                  className="p-1 text-[#808080] hover:text-[#E0E0E0] hover:bg-[#161616] transition-colors"
                  title="Add output unit to this day"
                >
                  <Plus className="w-3.5 h-3.5" />
                </button>
              </div>

              {/* Task Items in Day Column */}
              <div className="p-3 space-y-2 flex-1 overflow-y-auto">
                {dayTasks.length === 0 ? (
                  <div className="h-full flex items-center justify-center text-center p-4">
                    <span className="text-[11px] text-[#555] italic">No tasks scheduled</span>
                  </div>
                ) : (
                  dayTasks.map((task) => {
                    const linkedRole = appState.monthlyRoleGoals.find((r) => r.id === task.roleGoalId);

                    return (
                      <div
                        key={task.id}
                        className={`p-3 border transition-all space-y-2 ${
                          task.completed
                            ? 'bg-[#0A0A0A] border-[#222222] opacity-50'
                            : 'bg-[#161616] border-[#262626] hover:border-[#5FBF8C]'
                        }`}
                      >
                        <div className="flex items-start gap-2">
                          <button
                            id={`toggle-task-${task.id}`}
                            onClick={() => {
                              onToggleTask(task.id);
                              if (!task.completed) playBaselineChime();
                            }}
                            className="mt-0.5 flex-shrink-0"
                          >
                            <div className="w-3.5 h-3.5 border border-[#5FBF8C] flex items-center justify-center">
                              {task.completed && <div className="w-2 h-2 bg-[#5FBF8C]"></div>}
                            </div>
                          </button>

                          <div className="flex-1 min-w-0">
                            <h4 className={`text-xs font-medium leading-tight ${task.completed ? 'line-through text-[#808080]' : 'text-[#E0E0E0]'}`}>
                              {task.title}
                            </h4>
                          </div>

                          <button
                            onClick={() => onDeleteTask(task.id)}
                            className="text-[#808080] hover:text-[#E06C75] p-0.5 transition-colors flex-shrink-0"
                            title="Delete task"
                          >
                            <Trash2 className="w-3 h-3" />
                          </button>
                        </div>

                        {/* Output Unit & Role Badges */}
                        <div className="text-[10px] text-[#808080] pl-5 leading-tight">
                          Output: <span className="text-[#A3A3A3]">{task.outputUnit}</span>
                        </div>

                        <div className="flex items-center justify-between gap-1 pl-5 pt-1 text-[9px]">
                          {linkedRole && (
                            <span className="truncate max-w-[100px] text-[#5FBF8C] bg-[#0A0A0A] px-1.5 py-0.5 border border-[#262626] font-mono">
                              {linkedRole.roleName}
                            </span>
                          )}

                          {/* Quick Shift Button to Next Day */}
                          <div className="flex items-center gap-1 ml-auto">
                            <select
                              value={task.date}
                              onChange={(e) => onMoveTaskDate(task.id, e.target.value)}
                              className="bg-[#0A0A0A] border border-[#262626] text-[9px] text-[#808080] px-1 py-0.5 focus:outline-none"
                              title="Move task to another day"
                            >
                              {weekDays.map((wd) => (
                                <option key={wd.dateStr} value={wd.dateStr}>
                                  {wd.dayName} {wd.dayNum}
                                </option>
                              ))}
                            </select>
                          </div>
                        </div>
                      </div>
                    );
                  })
                )}
              </div>
            </div>
          );
        })}
      </div>

      {/* Add Task Modal */}
      {showAddModal && (
        <div className="fixed inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-[#111111] border border-[#262626] p-6 sm:p-8 max-w-md w-full space-y-5 shadow-2xl">
            <div className="flex items-center justify-between border-b border-[#262626] pb-3">
              <h2 className="text-lg font-serif text-[#E0E0E0]">
                Schedule Finite Agenda Task
              </h2>
              <span className="text-xs font-mono text-[#5FBF8C]">{formatDateDisplay(targetDateForAdd)}</span>
            </div>

            <form onSubmit={handleCreate} className="space-y-4">
              <div>
                <label className="text-[10px] uppercase tracking-widest text-[#808080] block mb-1">Task Title / Action</label>
                <input
                  type="text"
                  placeholder="e.g. Write migration script for legacy user profiles"
                  value={title}
                  onChange={(e) => setTitle(e.target.value)}
                  className="w-full px-3 py-2 bg-[#0A0A0A] border border-[#262626] text-xs text-[#E0E0E0] focus:outline-none focus:border-[#5FBF8C]"
                  required
                  autoFocus
                />
              </div>

              <div>
                <label className="text-[10px] uppercase tracking-widest text-[#808080] block mb-1">
                  Verifiable Output Deliverable Unit <span className="text-[#5FBF8C]">*</span>
                </label>
                <input
                  type="text"
                  placeholder="e.g. 1 script file committed & verified with tests"
                  value={outputUnit}
                  onChange={(e) => setOutputUnit(e.target.value)}
                  className="w-full px-3 py-2 bg-[#0A0A0A] border border-[#262626] text-xs text-[#E0E0E0] focus:outline-none focus:border-[#5FBF8C]"
                  required
                />
                <p className="text-[10px] text-[#808080] mt-1">
                  Track concrete output and completion, not feelings or effort stories.
                </p>
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="text-[10px] uppercase tracking-widest text-[#808080] block mb-1">Link to Monthly Role</label>
                  <select
                    value={roleGoalId}
                    onChange={(e) => setRoleGoalId(e.target.value)}
                    className="w-full px-3 py-2 bg-[#0A0A0A] border border-[#262626] text-xs text-[#E0E0E0] focus:outline-none"
                  >
                    <option value="">No linked role</option>
                    {appState.monthlyRoleGoals.map((r) => (
                      <option key={r.id} value={r.id}>
                        {r.roleName}
                      </option>
                    ))}
                  </select>
                </div>

                <div>
                  <label className="text-[10px] uppercase tracking-widest text-[#808080] block mb-1">Priority</label>
                  <select
                    value={priority}
                    onChange={(e) => setPriority(e.target.value as any)}
                    className="w-full px-3 py-2 bg-[#0A0A0A] border border-[#262626] text-xs text-[#E0E0E0] focus:outline-none"
                  >
                    <option value="high">High Priority</option>
                    <option value="medium">Medium Priority</option>
                    <option value="low">Low Priority</option>
                  </select>
                </div>
              </div>

              <div>
                <label className="text-[10px] uppercase tracking-widest text-[#808080] block mb-1">Target Date</label>
                <input
                  type="date"
                  value={targetDateForAdd}
                  onChange={(e) => setTargetDateForAdd(e.target.value)}
                  className="w-full px-3 py-2 bg-[#0A0A0A] border border-[#262626] text-xs text-[#E0E0E0] focus:outline-none font-mono"
                />
              </div>

              <div className="flex justify-end gap-3 pt-3 border-t border-[#262626]">
                <button
                  type="button"
                  onClick={() => setShowAddModal(false)}
                  className="px-4 py-2 border border-[#262626] text-[#808080] hover:text-[#E0E0E0] text-xs uppercase tracking-widest"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="px-5 py-2 bg-[#5FBF8C] hover:bg-[#7FD1A6] text-black text-xs uppercase tracking-widest font-semibold"
                >
                  Save Agenda Task
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import {
  Compass,
  Play,
  Pause,
  RotateCcw,
  CheckCircle2,
  X,
  Sparkles,
  Bot,
  Loader2,
  Shield,
} from 'lucide-react';
import { playBaselineChime, playMonasticBell } from '../services/sound';

interface AccessProtocolModalProps {
  isOpen: boolean;
  onClose: () => void;
}

const DEFAULT_PHASES = [
  {
    step: 1,
    name: 'Physiological Interruption',
    instructions: 'Stand up immediately. Drop your shoulders away from your ears. Take 3 slow, deep diaphragmatic breaths (4s in, 4s hold, 6s out). Shake out your hands.',
    durationSeconds: 30,
  },
  {
    step: 2,
    name: 'Data Disconnection',
    instructions: 'Recognize that fatigue, anxiety, or resistance are merely biological sensations, not moral verdicts. You are the observer of the data, not the sensation.',
    durationSeconds: 45,
  },
  {
    step: 3,
    name: 'Fixed Belief Anchor',
    instructions: 'Re-anchor your mind to the non-negotiable premise: "My identity as a disciplined builder is fixed. I do not negotiate with mood. I only negotiate strategy."',
    durationSeconds: 30,
  },
  {
    step: 4,
    name: 'Immediate Micro-Output',
    instructions: 'Perform one single physical execution unit right now (open the single active file, write 1 sentence, do 5 pushups). Break the inertia instantly.',
    durationSeconds: 60,
  },
];

export const AccessProtocolModal: React.FC<AccessProtocolModalProps> = ({
  isOpen,
  onClose,
}) => {
  const [currentPhaseIdx, setCurrentPhaseIdx] = useState(0);
  const [timeLeft, setTimeLeft] = useState(DEFAULT_PHASES[0].durationSeconds);
  const [isRunning, setIsRunning] = useState(false);
  const [phases, setPhases] = useState(DEFAULT_PHASES);
  const [currentState, setCurrentState] = useState('Resistant / Overthinking');
  const [isAiLoading, setIsAiLoading] = useState(false);

  useEffect(() => {
    let timer: any;
    if (isRunning && timeLeft > 0) {
      timer = setInterval(() => {
        setTimeLeft((prev) => prev - 1);
      }, 1000);
    } else if (isRunning && timeLeft === 0) {
      playBaselineChime();
      if (currentPhaseIdx < phases.length - 1) {
        setCurrentPhaseIdx((prev) => prev + 1);
        setTimeLeft(phases[currentPhaseIdx + 1].durationSeconds);
      } else {
        setIsRunning(false);
        playMonasticBell();
      }
    }
    return () => clearInterval(timer);
  }, [isRunning, timeLeft, currentPhaseIdx, phases]);

  if (!isOpen) return null;

  const currentPhase = phases[currentPhaseIdx];

  const handleToggleTimer = () => {
    setIsRunning(!isRunning);
  };

  const handleReset = () => {
    setIsRunning(false);
    setTimeLeft(currentPhase.durationSeconds);
  };

  const handleSelectPhase = (idx: number) => {
    setCurrentPhaseIdx(idx);
    setTimeLeft(phases[idx].durationSeconds);
    setIsRunning(false);
  };

  const handleTailorWithAi = async () => {
    setIsAiLoading(true);
    try {
      const res = await fetch('/api/ai/access-protocol', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ currentState }),
      });
      if (!res.ok) throw new Error('Failed to generate tailored protocol');
      const data = await res.json();
      if (data.phases && Array.isArray(data.phases)) {
        setPhases(data.phases);
        setCurrentPhaseIdx(0);
        setTimeLeft(data.phases[0].durationSeconds || 30);
      }
    } catch (e) {
      console.error(e);
    } finally {
      setIsAiLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4 overflow-y-auto">
      <div className="bg-[#111111] border border-[#262626] p-6 sm:p-8 max-w-xl w-full space-y-6 shadow-2xl relative my-8">

        {/* Header */}
        <div className="flex items-start justify-between gap-4 border-b border-[#262626] pb-4">
          <div className="space-y-1">
            <div className="flex items-center gap-2">
              <span className="p-1 bg-[#161616] text-[#5FBF8C] border border-[#262626]">
                <Compass className="w-3.5 h-3.5" />
              </span>
              <span className="text-[10px] uppercase font-mono tracking-widest text-[#5FBF8C]">
                Guided Somatic Reset
              </span>
            </div>
            <h2 className="text-xl font-serif text-[#E0E0E0]">
              Access Protocol
            </h2>
            <p className="text-xs text-[#808080] font-serif italic">
              4 structured somatic phases to break cognitive paralysis and restore execution state.
            </p>
          </div>

          <button
            onClick={onClose}
            className="p-1 text-[#808080] hover:text-[#E0E0E0] transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* State Selector & AI Tailor */}
        <div className="flex items-center justify-between gap-3 bg-[#0A0A0A] p-3 border border-[#262626]">
          <div className="flex-1">
            <label className="text-[9px] uppercase tracking-widest font-mono text-[#808080] block">Current State:</label>
            <select
              value={currentState}
              onChange={(e) => setCurrentState(e.target.value)}
              className="bg-transparent text-xs text-[#E0E0E0] focus:outline-none font-serif mt-0.5"
            >
              <option value="Resistant / Overthinking" className="bg-[#111111]">Resistant / Overthinking</option>
              <option value="Fatigued / Low Energy" className="bg-[#111111]">Fatigued / Low Energy</option>
              <option value="Scattered / Distracted" className="bg-[#111111]">Scattered / Distracted</option>
              <option value="Post-Interruption Spiral" className="bg-[#111111]">Post-Interruption Spiral</option>
            </select>
          </div>

          <button
            id="tailor-access-protocol-ai-btn"
            onClick={handleTailorWithAi}
            disabled={isAiLoading}
            className="px-3.5 py-1.5 bg-[#161616] hover:bg-[#222222] border border-[#262626] text-[#E0E0E0] text-[10px] uppercase tracking-widest font-semibold flex items-center gap-1.5 flex-shrink-0"
          >
            {isAiLoading ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Bot className="w-3.5 h-3.5 text-[#5FBF8C]" />}
            <span>Tailor Flow</span>
          </button>
        </div>

        {/* Phase Tabs */}
        <div className="grid grid-cols-4 gap-1.5">
          {phases.map((p, idx) => (
            <button
              key={p.step}
              onClick={() => handleSelectPhase(idx)}
              className={`p-2.5 text-left border transition-all ${
                currentPhaseIdx === idx
                  ? 'bg-[#161616] border-[#5FBF8C] text-[#5FBF8C]'
                  : 'bg-[#0A0A0A] border-[#262626] text-[#808080] hover:text-[#E0E0E0]'
              }`}
            >
              <div className="text-[9px] uppercase font-mono tracking-widest">Phase {p.step}</div>
              <div className="text-xs font-serif truncate mt-0.5">{p.name}</div>
            </button>
          ))}
        </div>

        {/* Active Phase Card */}
        <div className="p-6 bg-[#0A0A0A] border border-[#262626] space-y-4 text-center">
          <span className="text-[10px] font-mono uppercase tracking-widest text-[#5FBF8C]">
            Phase {currentPhase.step}: {currentPhase.name}
          </span>

          <p className="text-sm text-[#E0E0E0] font-serif leading-relaxed max-w-md mx-auto">
            {currentPhase.instructions}
          </p>

          {/* Countdown Clock */}
          <div className="text-4xl sm:text-5xl font-mono text-[#5FBF8C] py-2">
            00:{String(timeLeft).padStart(2, '0')}
          </div>

          {/* Controls */}
          <div className="flex items-center justify-center gap-3 pt-2">
            <button
              id="access-protocol-timer-toggle"
              onClick={handleToggleTimer}
              className="px-6 py-2 bg-[#5FBF8C] hover:bg-[#7FD1A6] text-black text-xs uppercase tracking-widest font-semibold flex items-center gap-2 shadow-sm"
            >
              {isRunning ? <Pause className="w-4 h-4" /> : <Play className="w-4 h-4" />}
              <span>{isRunning ? 'Pause' : 'Start Timer'}</span>
            </button>

            <button
              onClick={handleReset}
              className="p-2 bg-[#161616] hover:bg-[#222222] border border-[#262626] text-[#808080] hover:text-[#E0E0E0] transition-colors"
              title="Reset Timer"
            >
              <RotateCcw className="w-4 h-4" />
            </button>
          </div>
        </div>

        {/* Bottom Actions */}
        <div className="flex items-center justify-between pt-2 border-t border-[#262626]">
          <button
            onClick={() => {
              if (currentPhaseIdx > 0) handleSelectPhase(currentPhaseIdx - 1);
            }}
            disabled={currentPhaseIdx === 0}
            className="px-4 py-2 border border-[#262626] text-[#808080] hover:text-[#E0E0E0] disabled:opacity-30 text-xs uppercase tracking-widest"
          >
            Previous
          </button>

          {currentPhaseIdx < phases.length - 1 ? (
            <button
              onClick={() => handleSelectPhase(currentPhaseIdx + 1)}
              className="px-4 py-2 bg-[#161616] hover:bg-[#222222] border border-[#262626] text-[#E0E0E0] text-xs uppercase tracking-widest font-semibold"
            >
              Next Phase
            </button>
          ) : (
            <button
              onClick={onClose}
              className="px-5 py-2 bg-[#6BBF8E] hover:bg-[#7DCFA0] text-black text-xs uppercase tracking-widest font-semibold"
            >
              Complete Protocol
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import {
  Bot,
  Send,
  Sparkles,
  X,
  Loader2,
  ShieldAlert,
  Brain,
  Compass,
} from 'lucide-react';
import { AppState } from '../types';

interface AiStewardDrawerProps {
  isOpen: boolean;
  onClose: () => void;
  appState: AppState;
}

interface Message {
  role: 'user' | 'assistant';
  content: string;
}

export const AiStewardDrawer: React.FC<AiStewardDrawerProps> = ({
  isOpen,
  onClose,
  appState,
}) => {
  const [messages, setMessages] = useState<Message[]>([
    {
      role: 'assistant',
      content:
        'Peace be upon your discipline. I am your Steward OS Intelligence. I evaluate only outputs, consistency, and objective reality—without guilt, rationalization, or emotional stories. What is your inquiry or friction point?',
    },
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  if (!isOpen) return null;

  const handleSend = async (userPrompt?: string) => {
    const textToSend = userPrompt || input;
    if (!textToSend.trim() || isLoading) return;

    const newMessages: Message[] = [...messages, { role: 'user', content: textToSend }];
    setMessages(newMessages);
    setInput('');
    setIsLoading(true);

    try {
      const response = await fetch('/api/ai/steward-chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          message: textToSend,
          context: {
            currentStreak: appState.currentStreakNeverZero,
            failureLogsCount: appState.failurePatternLogs.length,
            neverZeroPassedToday: appState.dailyCompletions[appState.currentDate]?.neverZeroPassed,
            activeRoles: appState.monthlyRoleGoals.map((r) => r.roleName),
          },
        }),
      });

      if (!response.ok) throw new Error('Steward server error');
      const data = await response.json();

      setMessages([
        ...newMessages,
        {
          role: 'assistant',
          content: data.reply || 'Execution precedes motivation. What is the single output unit you will ship next?',
        },
      ]);
    } catch (e) {
      console.error(e);
      setMessages([
        ...newMessages,
        {
          role: 'assistant',
          content: 'The Steward is grounded in silence. Focus on shipping your current Minimum Viable Action.',
        },
      ]);
    } finally {
      setIsLoading(false);
    }
  };

  const quickPrompts = [
    'I feel heavy task resistance right now.',
    'Help me formulate my Single Adjustment.',
    'I caught myself in a Thinking Loop.',
    'Audit today’s friction as usable data.',
  ];

  return (
    <div className="fixed inset-y-0 right-0 z-50 w-full sm:w-96 bg-[#111111] border-l border-[#262626] shadow-2xl flex flex-col backdrop-blur-md">
      {/* Header */}
      <div className="p-4 border-b border-[#262626] flex items-center justify-between bg-[#0A0A0A]">
        <div className="flex items-center gap-2">
          <div className="p-1.5 bg-[#161616] text-[#5FBF8C] border border-[#262626]">
            <Bot className="w-4 h-4" />
          </div>
          <div>
            <h3 className="text-sm font-serif text-[#E0E0E0]">
              AI Steward Intelligence
            </h3>
            <span className="text-[9px] uppercase font-mono tracking-widest text-[#5FBF8C]">
              Monastic Objective Counsel
            </span>
          </div>
        </div>

        <button
          onClick={onClose}
          className="p-1 text-[#808080] hover:text-[#E0E0E0] transition-colors"
        >
          <X className="w-4 h-4" />
        </button>
      </div>

      {/* Quick Prompts Bar */}
      <div className="p-2.5 bg-[#0A0A0A] border-b border-[#262626] flex items-center gap-1.5 overflow-x-auto text-[10px] no-scrollbar">
        {quickPrompts.map((qp, idx) => (
          <button
            key={idx}
            onClick={() => handleSend(qp)}
            className="px-2.5 py-1 bg-[#161616] hover:bg-[#222222] text-[#808080] hover:text-[#5FBF8C] border border-[#262626] flex-shrink-0 transition-colors uppercase font-mono tracking-wider text-[9px]"
          >
            {qp}
          </button>
        ))}
      </div>

      {/* Messages List */}
      <div className="flex-1 overflow-y-auto p-4 space-y-3 text-xs leading-relaxed">
        {messages.map((m, idx) => (
          <div
            key={idx}
            className={`flex flex-col ${
              m.role === 'user' ? 'items-end' : 'items-start'
            }`}
          >
            <div
              className={`max-w-[85%] p-3.5 ${
                m.role === 'user'
                  ? 'bg-[#5FBF8C] text-black font-medium shadow-sm'
                  : 'bg-[#0A0A0A] border border-[#262626] text-[#E0E0E0] font-serif leading-relaxed'
              }`}
            >
              {m.content}
            </div>
            <span className="text-[9px] font-mono text-[#666] mt-1 px-1 tracking-widest uppercase">
              {m.role === 'user' ? 'You' : 'Steward'}
            </span>
          </div>
        ))}
        {isLoading && (
          <div className="flex items-center gap-2 text-[#808080] text-xs p-2">
            <Loader2 className="w-3.5 h-3.5 animate-spin text-[#5FBF8C]" />
            <span className="font-mono text-[10px] uppercase tracking-widest">Calibrating objective counsel...</span>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Input Field */}
      <div className="p-3 border-t border-[#262626] bg-[#0A0A0A]">
        <form
          onSubmit={(e) => {
            e.preventDefault();
            handleSend();
          }}
          className="flex items-center gap-2"
        >
          <input
            type="text"
            placeholder="Ask Steward..."
            value={input}
            onChange={(e) => setInput(e.target.value)}
            className="flex-1 px-3 py-2 bg-[#111111] border border-[#262626] text-xs text-[#E0E0E0] placeholder-[#555] focus:outline-none focus:border-[#5FBF8C]"
          />
          <button
            type="submit"
            disabled={isLoading || !input.trim()}
            className="p-2 bg-[#5FBF8C] hover:bg-[#7FD1A6] disabled:opacity-40 text-black transition-colors flex-shrink-0"
          >
            <Send className="w-4 h-4" />
          </button>
        </form>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
