      .filter(Boolean);

    onAddRoutine({
      name: name.trim(),
      timeStart,
      timeEnd,
      isProtected,
      status: 'pending',
      items: items.length > 0 ? items : ['Primary focus output block'],
    });

    setName('');
    setItemsText('');
    setShowAddModal(false);
  };

