import { playMonasticBell, playBaselineChime } from '../services/sound';

interface GratitudeScanModalProps {
  isOpen: boolean;
  onClose: () => void;
  todayScan?: GratitudeScan;
  onSaveScan: (scan: GratitudeScan) => void;
  onToggleProofAction: () => void;
}

